<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Pop Archery</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #1a1a2e; }
  canvas { display: block; width: 100vw; height: 100vh; cursor: crosshair; }
  #ui {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    pointer-events: none; font-family: 'Press Start 2P', monospace;
  }
  .overlay {
    position: absolute; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 24px;
    background: rgba(10,10,30,0.85); pointer-events: auto;
  }
  .overlay.hidden { display: none; }
  h1 { color: #ffd700; font-size: 28px; text-shadow: 3px 3px 0 #b8860b; }
  h2 { color: #fff; font-size: 20px; }
  .btn {
    font-family: 'Press Start 2P', monospace; font-size: 14px;
    padding: 14px 28px; background: #ffd700; color: #1a1a2e;
    border: 4px solid #b8860b; cursor: pointer; pointer-events: auto;
    box-shadow: 4px 4px 0 #8b6914;
  }
  .btn:hover { background: #ffe44d; }
  .btn:active { transform: translate(2px,2px); box-shadow: 2px 2px 0 #8b6914; }
  .hint { color: #aaa; font-size: 10px; line-height: 1.8; text-align: center; }
  #hud {
    position: absolute; top: 16px; left: 16px; color: #fff; font-size: 12px;
    text-shadow: 2px 2px 0 #000;
  }
  #timerbar {
    position: absolute; top: 0; left: 0; height: 6px; background: #ff4444;
    width: 100%; transition: width 0.1s linear;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="ui">
  <div id="timerbar"></div>
  <div id="hud">SCORE 0</div>
  <div id="startScreen" class="overlay">
    <h1>BALLOON POP</h1>
    <h2>ARCHERY</h2>
    <button class="btn" id="startBtn">START</button>
    <div class="hint">AIM WITH MOUSE<br>PULL BACK TO CHARGE<br>RELEASE TO SHOOT<br>POP ALL BALLOONS BEFORE TIME RUNS OUT</div>
  </div>
  <div id="endScreen" class="overlay hidden">
    <h1 id="endTitle">GAME OVER</h1>
    <h2 id="endScore">SCORE: 0</h2>
    <button class="btn" id="retryBtn">PLAY AGAIN</button>
  </div>
</div>
<script>
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W, H;
function resize() { W = canvas.width = innerWidth; H = canvas.height = innerHeight; }
addEventListener('resize', resize); resize();

