function audio() { if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)(); return actx; }
function playShoot() {
  const a = audio(); const o = a.createOscillator(); const g = a.createGain();
  o.type = 'sawtooth'; o.frequency.setValueAtTime(200, a.currentTime);
  o.frequency.exponentialRampToValueAtTime(80, a.currentTime + 0.15);
  g.gain.setValueAtTime(0.3, a.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, a.currentTime + 0.15);
  o.connect(g); g.connect(a.destination); o.start(); o.stop(a.currentTime + 0.15);
}
